console.log("Worker starting...");

const jobHandlers: Record<string, (job: Job) => Promise<void>> = {
  site_import: async (job) => {
    const handler = Container.get(ProcessSiteImportCommand);
    await handler.execute({ jobId: job.data.jobId });
  },
};

